refs:
#include <algorithm>
#include <print>
#include <ranges>

int main() {
    auto out = std::views::iota(1, 101)
             | std::views::filter([](int x) { return x % 3 == 0; })
             | std::views::transform([](int x) { return x * x; })
             | std::views::take(5);
    for (int v : out) std::print("{} ", v);
    std::println("");

    auto swapped = std::views::iota(1, 101)
                 | std::views::transform([](int x) { return x * x; })
                 | std::views::filter([](int x) { return x % 3 == 0; })
                 | std::views::take(5);
    for (int v : swapped) std::print("{} ", v);
    std::println("");
    // 这一对换顺序结果一样：平方不改变能不能被 3 整除，两段都一对一保序；take 挪到前面就不一样了
    return 0;
}

